{"id":"puzzle-155","h":"3a1c4ef85229ad28dcb627f112042440","n":[{"category":"Played for Juventus in 2025-26","players":["Dušan Vlahović","Kenan Yıldız","Teun Koopmeiners","Andrea Cambiaso"],"difficulty":"easy"},{"category":"From Morocco","players":["Achraf Hakimi","Hakim Ziyech","Youssef En-Nesyri","Sofiane Boufal"],"difficulty":"medium"},{"category":"Played for both Manchester United AND Chelsea","players":["Juan Mata","Nemanja Matić","Mark Hughes","Radamel Falcao"],"difficulty":"hard"},{"category":"Won the Ballon d'Or before turning 22","players":["Ronaldo Nazário","Michael Owen","Lionel Messi","George Best"],"difficulty":"insane"}]}
]$pl$;
  rec record;
  rewritten int := 0;
  already int := 0;
  drifted text[] := '{}';
begin
  if md5(payload) <> 'feefc809b357838e733ad8e743a7de4d' then
    raise exception 'Round 1553: payload checksum mismatch, nothing applied';
  end if;
  for rec in select * from jsonb_to_recordset(payload::jsonb) as x(id text, h text, n jsonb) loop
    if exists (select 1 from public.connections_puzzles c where c.puzzle_id = rec.id and c.groups_json = rec.n) then
      already := already + 1;
    else
      update public.connections_puzzles c
         set groups_json = rec.n
       where c.puzzle_id = rec.id
         and md5(c.groups_json::text) = rec.h;
      if found then rewritten := rewritten + 1; else drifted := drifted || rec.id; end if;
    end if;
  end loop;
  if rewritten + already <> 57 then
    raise exception 'Round 1553: % rewritten, % already current, drifted %: nothing applied', rewritten, already, drifted;
  end if;
  raise notice 'Round 1553: % rewritten, % already current, 0 drifted', rewritten, already;
end
$$;
